import threading
import time
from typing import Any, Optional

class ThreadSafeRingBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('Capacity must be positive')
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.head = 0
        self.tail = 0
        self.count = 0
        self.lock = threading.Lock()
        self.not_full = threading.Condition(self.lock)
        self.not_empty = threading.Condition(self.lock)

    def push(self, item: Any, timeout: Optional[float] = None) -> bool:
        deadline = time.time() + timeout if timeout is not None else None
        with self.lock:
            while self.count == self.capacity:
                if timeout is not None:
                    remaining = deadline - time.time()
                    if remaining <= 0:
                        return False
                    if not self.not_full.wait(remaining):
                        return False
                else:
                    self.not_full.wait()
            self.buffer[self.tail] = item
            self.tail = (self.tail + 1) % self.capacity
            self.count += 1
            self.not_empty.notify()
            return True

    def pop(self, timeout: Optional[float] = None) -> tuple[bool, Any]:
        deadline = time.time() + timeout if timeout is not None else None
        with self.lock:
            while self.count == 0:
                if timeout is not None:
                    remaining = deadline - time.time()
                    if remaining <= 0:
                        return False, None
                    if not self.not_empty.wait(remaining):
                        return False, None
                else:
                    self.not_empty.wait()
            item = self.buffer[self.head]
            self.buffer[self.head] = None
            self.head = (self.head + 1) % self.capacity
            self.count -= 1
            self.not_full.notify()
            return True, item

    def size(self) -> int:
        with self.lock:
            return self.count

    def is_empty(self) -> bool:
        with self.lock:
            return self.count == 0

    def is_full(self) -> bool:
        with self.lock:
            return self.count == self.capacity

def bellman_ford_negative_cycles(
    n: int,
    edges: list[tuple[int, int, float]],
    source: int
) -> tuple[bool, dict[int, float], list[int]]:
    dist = [float('inf')] * n
    parent = [-1] * n
    dist[source] = 0.0
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v] - 1e-12:
                dist[v] = dist[u] + w
                parent[v] = u
                updated = True
        if not updated:
            break
    cycle_node = -1
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v] - 1e-12:
            cycle_node = v
            parent[v] = u
            break
    if cycle_node != -1:
        curr = cycle_node
        for _ in range(n):
            curr = parent[curr]
        cycle = []
        start = curr
        while True:
            cycle.append(curr)
            if curr == start and len(cycle) > 1:
                break
            curr = parent[curr]
        cycle.reverse()
        return True, {}, cycle
    distances = {i: dist[i] for i in range(n)}
    return False, distances, []

import threading
import time
from typing import Optional

class ThreadSafeMemoryPool:
    def __init__(self, block_size: int, pool_capacity: int):
        self.block_size = block_size
        self.pool_capacity = pool_capacity
        self.blocks = [bytearray(block_size) for _ in range(pool_capacity)]
        self.available_ids = list(range(pool_capacity))
        self.leased_ids = set()
        self.lock = threading.Lock()
        self.cond = threading.Condition(self.lock)

    def acquire(self, timeout: Optional[float] = None) -> tuple[Optional[int], Optional[bytearray]]:
        deadline = time.time() + timeout if timeout is not None else None
        with self.lock:
            while not self.available_ids:
                if timeout is not None:
                    remaining = deadline - time.time()
                    if remaining <= 0:
                        return None, None
                    if not self.cond.wait(remaining):
                        return None, None
                else:
                    self.cond.wait()
            bid = self.available_ids.pop()
            self.leased_ids.add(bid)
            return bid, self.blocks[bid]

    def release(self, block_id: int) -> bool:
        with self.lock:
            if block_id not in self.leased_ids:
                return False
            self.leased_ids.remove(block_id)
            self.available_ids.append(block_id)
            self.cond.notify()
            return True

    def active_leases_count(self) -> int:
        with self.lock:
            return len(self.leased_ids)

    def available_count(self) -> int:
        with self.lock:
            return len(self.available_ids)
